shader.vshader:
        
				uniform highp mat4 inWorldViewProjMatrix;
				uniform highp float inTime;
				uniform highp float OutlineSize;
				attribute vec3 inPos;
				attribute vec3 inNormal;
				
				void main()
				{
					highp float w = (inWorldViewProjMatrix * vec4(inPos, 1.0)).w;
					highp float t = abs(sin(inTime*3.0) * OutlineSize)*w;
					gl_Position = inWorldViewProjMatrix * vec4(inPos+inNormal*t, 1.0);
				}

shader.fshader:
        
				
				uniform highp float OutlineSize;
				uniform highp float inTime;
				void main()
				{
					
					if (OutlineSize<0.002)
						discard;
					
					gl_FragColor = vec4(1.0);
				}

shader.vshader:
        
				uniform mat4 inWorldViewProjMatrix;
				uniform highp vec3 inTextureMatrix1[2];
				
				attribute vec3 inPos;
				attribute vec2 inUV0;
				attribute vec2 inUV1;
				
				varying highp vec2 uv0;
				varying highp vec2 uv1;
				
				void main()
				{
					gl_Position = inWorldViewProjMatrix * vec4(inPos, 1.0);
					uv0 = inUV0;
					uv1 = vec2(dot(inTextureMatrix1[0], vec3(inUV1, 1.)), dot(inTextureMatrix1[1], vec3(inUV1, 1.)));
				}

shader.fshader:
        
				uniform lowp float ColorScale;
				
				varying highp vec2 uv0;
				varying highp vec2 uv1;
				uniform lowp float isZPass;
				uniform sampler2D diffuseMap;
				uniform sampler2D shadowMap;

				
				void main()
				{
					if(isZPass>0.5)
					discard;
					lowp vec4 diffuseCol = texture2D(diffuseMap, uv0);
					lowp vec4 shadowCol = texture2D(shadowMap, uv1);
					
					lowp vec4 color = diffuseCol * shadowCol * ColorScale;
					//color = vec3(pow(color.r, 0.9), pow(color.g, 0.9), pow(color.b, 0.9));
					
					gl_FragColor = color; 
				
				}
